CREATE TABLE sub13_sales (sale_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, amount INTEGER NOT NULL);
INSERT INTO sub13_sales VALUES (1, 'Asha', 50), (2, 'Asha', 70), (3, 'Bilal', 40), (4, 'Bilal', 80), (5, 'Mira', 30);
SELECT customer, total_amount FROM (SELECT customer, SUM(amount) AS total_amount FROM sub13_sales GROUP BY customer) AS customer_totals WHERE total_amount > 100 ORDER BY customer;

